    private const string ExampleInput = "3-5\n10-14\n16-20\n12-18\n\n1\n5\n8\n11\n17\n32";

    private long m_result;

    public long GetResultPartOne()
    {
        string[] input = MyInput.Split('\n')[..];
        int indexOfInputSplitter = input.IndexOf(string.Empty);
        string[] ranges = input[..indexOfInputSplitter];
        string[] ids = input[(indexOfInputSplitter + 1)..];
        List<(long from, long To)> freshRanges = [];

        foreach (string range in ranges)
        {
            string[] split = range.Split('-');
            long start = long.Parse(split[0]);
            long end = long.Parse(split[1]);
            
            freshRanges.Add((start, end));
        }

        foreach (string idAsString in ids)
        {
            long id =  long.Parse(idAsString);
            if (freshRanges.Any(freshRange => freshRange.from <= id && freshRange.To >= id)) m_result++;
        }
        
        return m_result;
    }
    
    public long GetResultPartTwo()
    {
        string[] input = MyInput.Split('\n')[..];
        int indexOfInputSplitter = input.IndexOf(string.Empty);
        string[] ranges = input[..indexOfInputSplitter];

        List<(long from, long To)> freshRanges = [];
        
        foreach (string range in ranges)
        {
            string[] split = range.Split('-');
            long start = long.Parse(split[0]);
            long end = long.Parse(split[1]);
            
            List<(long from,long to)> overlappingRanges = freshRanges.Where(
                freshRange => 
                    (freshRange.from <= start && freshRange.To >= start) 
                    || (freshRange.from <= end && freshRange.To >= end)
                    || (freshRange.from > start && freshRange.To < end)).ToList();
            
            if (overlappingRanges.Count != 0)
            {
                // merge overlapping ranges and remove old ranges
                overlappingRanges.Add((start, end));
                freshRanges.Add((overlappingRanges.MinBy(r => r.from).from, overlappingRanges.MaxBy(r => r.to).to));
                overlappingRanges.Remove((start, end));
                overlappingRanges.ForEach(r => freshRanges.Remove(r));
            }
            else
            {
                // no overlapping ranges => just add it
                freshRanges.Add((start, end));
            }
        }

        foreach ((long from, long to) in freshRanges)
        {
            m_result += to - from + 1;
        }
        
        return m_result;
    }
